CREATE OR REPLACE FUNCTION private.assert_catch_tradable()
 RETURNS trigger
 LANGUAGE plpgsql
AS $function$
declare
  c public.catches;
begin
  select * into c from public.catches where id = new.catch_id;
  if c.id is null then raise exception 'That Pokémon is not available.'; end if;
  if c.locked or c.favorite then raise exception 'A locked or favorite Pokémon cannot be traded.'; end if;
  if exists (select 1 from public.species s where s.dex = c.dex and s.tradable = false) then
    raise exception 'That Pokémon cannot be traded.';
  end if;
  if c.trade_locked_until is not null and c.trade_locked_until > now() then
    raise exception 'That Pokémon was just received. Wait a few minutes before trading it again.';
  end if;
  return new;
end;
$function$

CREATE OR REPLACE FUNCTION public.play_trade_accept(p_offer_id uuid)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
declare
  uid uuid := auth.uid();
  o public.trade_offers;
  l public.trade_listings;
  listed public.catches;
  offered public.catches;
begin
  if uid is null then raise exception 'Sign in first.' using errcode = '42501'; end if;
  select * into o from public.trade_offers where id = p_offer_id and status = 'pending' for update;
  if o.id is null then raise exception 'That offer is gone.'; end if;
  select * into l from public.trade_listings where id = o.listing_id and user_id = uid and status = 'open' for update;
  if l.id is null then raise exception 'Only the listing trainer can accept, and the listing must still be open.'; end if;
  select * into listed from public.catches where id = l.catch_id and user_id = uid and transferred_at is null for update;
  select * into offered from public.catches where id = o.catch_id and user_id = o.user_id and transferred_at is null for update;
  if listed.id is null or offered.id is null then
    raise exception 'One of those Pokémon is no longer available.';
  end if;
  if listed.locked or listed.favorite or offered.locked or offered.favorite then
    raise exception 'A locked or favorite Pokémon cannot be traded.';
  end if;
  if exists (select 1 from public.species s where s.dex = listed.dex and s.tradable = false)
     or exists (select 1 from public.species s where s.dex = offered.dex and s.tradable = false) then
    raise exception 'That Pokémon cannot be traded.';
  end if;
  update public.catches set user_id = o.user_id where id = listed.id;
  update public.catches set user_id = uid where id = offered.id;
  perform private.pull_from_team(uid, listed.id);
  perform private.pull_from_team(o.user_id, offered.id);
  perform private.mark_trade_receive(o.user_id, listed.id, uid);
  perform private.mark_trade_receive(uid, offered.id, o.user_id);
  update public.trainer_stats set trades_done = trades_done + 1, traded_away = traded_away + 1, traded_in = traded_in + 1, updated_at = now() where user_id = uid;
  update public.trainer_stats set trades_done = trades_done + 1, traded_away = traded_away + 1, traded_in = traded_in + 1, updated_at = now() where user_id = o.user_id;
  perform private.trade_xp(uid, 'gts:' || l.id::text);
  perform private.trade_xp(o.user_id, 'gts:' || l.id::text);
  update public.trade_listings set status = 'completed' where id = l.id;
  update public.trade_offers set status = 'accepted' where id = o.id;
  update public.trade_offers set status = 'declined' where listing_id = l.id and status = 'pending';
  update public.trade_listings set status = 'cancelled' where catch_id in (listed.id, offered.id) and status = 'open';
  update public.trade_offers set status = 'declined' where status = 'pending' and catch_id in (listed.id, offered.id);
  perform private.evaluate_achievements(uid, true);
  perform private.evaluate_achievements(o.user_id, true);
  return jsonb_build_object('ok', true, 'message', 'Trade complete. The Pokémon swapped trainers.');
end;
$function$

CREATE OR REPLACE FUNCTION public.play_trade_create(p_catch_id uuid, p_want_dex integer DEFAULT NULL::integer, p_note text DEFAULT NULL::text, p_accept_any boolean DEFAULT true, p_want_gender text DEFAULT NULL::text, p_want_shiny boolean DEFAULT false)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
declare
  uid uuid := auth.uid();
  c public.catches;
  listing public.trade_listings;
  note text := left(btrim(coalesce(p_note, '')), 80);
  accept boolean := coalesce(p_accept_any, true);
  want_gender text := nullif(p_want_gender, '');
  want_shiny boolean := coalesce(p_want_shiny, false);
  rate int;
begin
  if uid is null then
    raise exception 'Sign in to list a Pokémon for trade.' using errcode = '42501';
  end if;
  select * into c from public.catches where id = p_catch_id and user_id = uid and transferred_at is null;
  if c.id is null then
    raise exception 'That Pokémon is not in your storage.';
  end if;
  if p_want_dex is not null and (p_want_dex < 1 or p_want_dex > 151) then
    raise exception 'Wanted Pokémon must be from the Kanto Pokédex.';
  end if;
  if p_want_dex is null then
    accept := true;
    want_gender := null;
    want_shiny := false;
  else
    rate := private.lgpe_gender_rate(p_want_dex);
    if rate is null or rate = -1 or rate = 0 or rate = 8 then
      want_gender := null;
    elsif want_gender is not null and want_gender not in ('Male', 'Female') then
      want_gender := null;
    end if;
  end if;
  if p_want_dex is null and accept is not true then
    raise exception 'Choose a Pokémon you want, or take other offers.';
  end if;
  perform private.pull_from_team(uid, c.id);
  insert into public.trade_listings (catch_id, user_id, want_dex, note, accept_any, want_gender, want_shiny)
  values (c.id, uid, p_want_dex, nullif(note, ''), accept, want_gender, want_shiny)
  on conflict (catch_id) do update
    set status = 'open',
        want_dex = excluded.want_dex,
        note = excluded.note,
        accept_any = excluded.accept_any,
        want_gender = excluded.want_gender,
        want_shiny = excluded.want_shiny,
        user_id = uid,
        created_at = now()
    where public.trade_listings.status <> 'open'
  returning * into listing;
  if listing.id is null then
    raise exception 'That Pokémon is already on the trade board.';
  end if;
  return jsonb_build_object('ok', true, 'message', 'Listed on the Global Trade System.', 'listing', private.trade_listing_json(listing));
end;
$function$

CREATE OR REPLACE FUNCTION public.play_trade_offer(p_listing_id uuid, p_catch_id uuid)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
declare
  uid uuid := auth.uid();
  l public.trade_listings;
  c public.catches;
begin
  if uid is null then
    raise exception 'Sign in to make an offer.' using errcode = '42501';
  end if;
  select * into l from public.trade_listings where id = p_listing_id and status = 'open';
  if l.id is null then
    raise exception 'That listing is no longer open.';
  end if;
  if l.user_id = uid then
    raise exception 'You cannot offer on your own listing.';
  end if;
  select * into c from public.catches where id = p_catch_id and user_id = uid and transferred_at is null;
  if c.id is null then
    raise exception 'That Pokémon is not in your storage.';
  end if;
  if exists (select 1 from public.trade_listings t where t.catch_id = c.id and t.status = 'open') then
    raise exception 'Take that Pokémon off the trade board before offering it.';
  end if;
  if l.want_dex is not null and coalesce(l.accept_any, true) = false then
    if c.dex is distinct from l.want_dex then
      raise exception 'This trainer is only looking for that species.';
    end if;
    if l.want_gender in ('Male', 'Female') and c.gender is distinct from l.want_gender then
      raise exception 'This trainer wants that gender.';
    end if;
    if coalesce(l.want_shiny, false) and position('shiny' in lower(coalesce(c.variant, ''))) = 0 then
      raise exception 'This trainer wants a shiny.';
    end if;
  end if;
  perform private.pull_from_team(uid, c.id);
  insert into public.trade_offers (listing_id, user_id, catch_id)
  values (l.id, uid, c.id);
  return jsonb_build_object('ok', true, 'message', 'Offer sent.');
end;
$function$
